#include "stdlib/math/base/special/expitf.h"
#include "stdlib/constants/float32/nan.h"
#include "stdlib/math/base/special/expf.h"
#include "stdlib/math/base/assert/is_nanf.h"

/**
* Evaluates the standard logistic function for a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_expitf( 0.0f );
* // returns 0.5f
*/
float stdlib_base_expitf( const float x ) {
	if ( stdlib_base_is_nanf( x ) ) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	return 1.0f / ( 1.0f + stdlib_base_expf( -x ) );
}
